#include <vector>
#include <algorithm>

class Solution {
public:
    int maxDistance(std::vector<int>& colors) {
        int n = colors.size();
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            if (colors[i] != colors[0]) ans = std::max(ans, i);
            if (colors[i] != colors[n - 1]) ans = std::max(ans, n - 1 - i);
        }
        return ans;
    }
};

class Solution {
    public int maxDistance(int[] colors) {
        int n = colors.length;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (colors[i] != colors[0]) ans = Math.max(ans, i);
            if (colors[i] != colors[n - 1]) ans = Math.max(ans, n - 1 - i);
        }
        return ans;
    }
}

